import React from 'react';
import { Package } from 'lucide-react';

const TopProducts = () => {
  const topProducts = [
    { name: 'Casque Premium', sales: 342, revenue: '$12,450', stock: 45 },
    { name: 'Souris sans fil', sales: 289, revenue: '$8,670', stock: 12 },
    { name: 'Support portable', sales: 156, revenue: '$5,460', stock: 23 },
  ];

  return (
    <div className="bg-gradient-to-br from-white to-white/70 dark:from-neutral-900 dark:to-neutral-900/70 backdrop-blur-xl rounded-2xl p-6 shadow-lg border border-white/30 dark:border-neutral-800/50">
      <h3 className="text-lg font-bold text-neutral-900 dark:text-white mb-6">Produits populaires</h3>

    </div>
  );
};

export default TopProducts;
